INSERT INTO public.catalog_features (feature_key, domain_type, product_key, subproduct_key, name, summary, payload, maturity, content_hash, source_provenance) VALUES ('platform.configuration_naming.config_cascade_resolve', 'platform_service', NULL, NULL, 'Resolver configuração efetiva', 'Resolver configuração efetiva deve aplicar defaults, inheritance, locks, overrides e source attribution como invariante transversal da plataforma, sem forks específicos por produto.', '{"feature_key":"platform.configuration_naming.config_cascade_resolve","domain_type":"platform_service","service_key":"platform.configuration_naming","name":"Resolver configuração efetiva","description":"Resolver configuração efetiva deve aplicar defaults, inheritance, locks, overrides e source attribution como invariante transversal da plataforma, sem forks específicos por produto.","user_value":["Fornece resolver configuração efetiva como serviço transversal.","Mantém comportamento consistente entre superfícies e produtos."],"actors":["master_operator","agency_admin","tenant_admin","release_manager"],"preconditions":["authority_valid","configuration_snapshot_available","release_context_known"],"states":["draft","ready","active","degraded","blocked","retired"],"entities":["ConfigDefinition","ConfigPublication","EffectiveConfig","NamingDefinition","NamingPublication","FeatureFlag"],"operations":["effective-config-resolve","public-host-resolve"],"pages":["agency.private.cascade","master.private.cascade","master.private.registries","tenant.private.settings"],"configuration_keys":["config.cascade_order","config.diff_required","config.inheritance_enabled","config.locked_prefixes","config.override_policy","config.preview_enabled","config.rollback_window_days","config.snapshot_on_publish"],"events":["platform.configuration_naming.config_cascade_resolve.requested","platform.configuration_naming.config_cascade_resolve.completed","platform.configuration_naming.config_cascade_resolve.failed"],"policies":["tenant_isolation","least_privilege","audit_required","compatibility_required","evidence_required"],"functional_requirements":["O serviço deve aplicar defaults, inheritance, locks, overrides e source attribution.","O contrato deve ser consumido por APIs e registries versionados.","Estado e evidence devem ser consultáveis sem expor segredo ou dado indevido."],"acceptance_criteria":["A execução autorizada de resolver configuração efetiva produz o estado esperado de ConfigDefinition e emite `platform.configuration_naming.config_cascade_resolve.completed` com correlation ID.","A repetição da mesma intenção com a mesma idempotency key não produz efeito duplicado nem evento material duplicado.","Um actor sem membership, permission ou entitlement efetivo recebe denial explícito e não observa dados protegidos.","Input inválido ou dependency failure encerra sem alteração parcial e registra erro taxonomizado e auditável.","Quando houver interface browser, loading, empty, validation, error, success, responsive Grid, teclado e screen reader são cobertos por Carbon."],"test_requirements":["contract_platform_configuration_naming_config_cascade_resolve","authorization_negative_and_cross_tenant","transaction_and_idempotency","event_audit_and_observability","carbon_accessibility_when_ui_exists"],"metrics":["availability","latency","error_rate","policy_denial_rate","change_failure_rate"],"maturity":"development","release_gate":"platform_contract+security+operability","source_basis":{"derived_from":"platform.configuration_naming","classification":"normative_expansion_v0.9.0"},"operation_contracts":[{"operation_id":"effective-config-resolve","domain":"Configuration","access":"authenticated","execution":"edge","bundle":"tenant-api","responsibility":"Resolver snapshot de configuração pela Cascade e revisão publicada."},{"operation_id":"public-host-resolve","domain":"Tenancy","access":"public","execution":"edge","bundle":"public-api","responsibility":"Resolver host, tenant, locale, theme e proje