INSERT INTO public.catalog_features (feature_key, domain_type, product_key, subproduct_key, name, summary, payload, maturity, content_hash, source_provenance) VALUES ('product.academy_ops.assessment_evidence.assessment_build', 'product', 'product.academy_ops', 'product.academy_ops.assessment_evidence', 'Construir assessment', 'Construir assessment deve compor itens, rubric, tentativas, tempo, accessibility e policy de finalização, preservando autorização, tenant isolation, idempotência, provenance e auditabilidade.', '{"feature_key":"product.academy_ops.assessment_evidence.assessment_build","domain_type":"product","product_key":"product.academy_ops","subproduct_key":"product.academy_ops.assessment_evidence","name":"Construir assessment","description":"Construir assessment deve compor itens, rubric, tentativas, tempo, accessibility e policy de finalização, preservando autorização, tenant isolation, idempotência, provenance e auditabilidade.","user_value":["Permite construir assessment com contexto e controles explícitos.","Reduz drift entre interface, operação, dados e evidence."],"actors":["learner","instructor","tenant_learning_admin","assessor","compliance_manager"],"preconditions":["authenticated_or_explicit_public_boundary","effective_tenant_context","required_entitlement","authorization_policy_allow"],"states":["draft","ready","active","blocked","completed","archived"],"entities":["Assessment","AssessmentVersion","Submission","Evidence","ScoreResult"],"operations":[],"pages":[],"configuration_keys":[],"events":["product.academy_ops.assessment_evidence.assessment_build.requested","product.academy_ops.assessment_evidence.assessment_build.completed","product.academy_ops.assessment_evidence.assessment_build.failed"],"policies":["tenant_isolation","least_privilege","purpose_limitation","audit_required","idempotency_for_mutation"],"functional_requirements":["A implementação deve compor itens, rubric, tentativas, tempo, accessibility e policy de finalização.","Toda mutação deve preservar actor, tenant, correlation, idempotency e audit evidence.","A resposta deve distinguir sucesso, validação, policy denial, dependency failure e entitlement absence."],"acceptance_criteria":["A execução autorizada de construir assessment produz o estado esperado de Assessment e emite `product.academy_ops.assessment_evidence.assessment_build.completed` com correlation ID.","A repetição da mesma intenção com a mesma idempotency key não produz efeito duplicado nem evento material duplicado.","Um actor sem membership, permission ou entitlement efetivo recebe denial explícito e não observa dados protegidos.","Input inválido ou dependency failure encerra sem alteração parcial e registra erro taxonomizado e auditável.","Quando houver interface browser, loading, empty, validation, error, success, responsive Grid, teclado e screen reader são cobertos por Carbon."],"test_requirements":["contract_product_academy_ops_assessment_evidence_assessment_build","authorization_negative_and_cross_tenant","transaction_and_idempotency","event_audit_and_observability","carbon_accessibility_when_ui_exists"],"metrics":["success_rate","latency","policy_denial_rate","retry_rate","user_outcome"],"maturity":"development","release_gate":"contract+security+data+ui_when_applicable+observability","source_basis":{"derived_from":"product.academy_ops.assessment_evidence","classification":"normative_expansion_v0.9.0"},"operation_contracts":[],"entitlement_profiles":["entitlement.product_standard"]}'::jsonb, 'development', '05899c3c3adf9dc9afab3cd063e7f8a17312b074d5a97df89112323b98bb458a', '{"source_repo":"cestari-studio/genOS","source_sha":"ffd97fa93ab425fff6bac5015d34944ef924090c","source_path":"docs/specs/v0.9.0/registries/feature-registry.json","source_blob_sha":"d4f32dea850083c96cd4e09d9402f471473f1628","registry_version":"0.9.0"}'::jsonb) ON CONFLICT (feature_key) DO UPDATE SET domain_type = EXCLUDED.domain_type, product_key = EXCLUDED.product_key, subproduct_key = EXCLUDED.subpr